window.SAQ_PAPER_QUESTIONS["2020-2-st-george"]=[{"number":1,"title":"","stemText":"An elderly lady presents after a trip and fall forward, hitting her right orbit on a doorknob. She is on dual antiplatelet therapy. There are no other injuries. An image of her injured eye is shown below :","parts":[{"id":"a","label":"Part A","prompt":"What are the main abnormalities seen on inspection? (2 marks) 1. 2.\nP a g e 2 | 39"},{"id":"b","label":"Part B","prompt":"In addition to cessation of the dual antiplatelet therapy, list five (5) key actions for managing this injury (with drug doses where relevant) and provide a rationale for each. (10 marks) Key actions Rationale\nP a g e 3 | 39"}],"propPages":["asset:img98dd0ac8d694248dfa"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Complete hyphaema of right eye with fluid level in the anterior chamber</div><div class=\"answer-line\">ii.</div><div class=\"answer-line\">Patchy subconjunctival haemorrhage</div><div class=\"answer-line\"><strong>b)</strong><strong> </strong><strong>In addition to cessation of the dual antiplatelet therapy, list five (5) key management </strong></div><div class=\"answer-line\"><strong>principles for this injury and give a rationale for each. (10 marks) </strong></div><div class=\"answer-line\"><strong>Management Principle </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Eye rest</strong> (pad affected eye and no</td><td>Reduces pupillary play and risk of further bleed</td></tr><tr><td>reading/television)</td><td></td></tr><tr><td><strong>Strict bed rest at 30 degrees head up </strong></td><td>Allows for sedimentation, clears angle</td></tr><tr><td><strong>Treat pain and nausea </strong>(PO Panadol, PO/IV</td><td>Can be caused by increased IOP and itself</td></tr><tr><td>opiate – avoid NSAIDs – PO/IV antiemetic)</td><td>increase IOP</td></tr><tr><td><strong>Cycloplegic agent </strong>(eg. atropine 1% daily dose</td><td>Reduce movement of intraocular structures</td></tr><tr><td>or tropicamide)</td><td>(prevent posterior synechiae, ciliary spasm,</td></tr><tr><td>stretching of vessels)</td><td></td></tr><tr><td>Reduce elevated IOP (acetazolamide 500mg</td><td>Prevent / treat acute glaucoma, reduce pain</td></tr><tr><td>PO/IV)</td><td></td></tr><tr><td>Topical corticosteroid</td><td>Prevent posterior synechiae, possibly reduce</td></tr><tr><td>rate of rebleed</td><td></td></tr><tr><td>Ophthalmology consultation and admission</td><td>If hyphaema &gt;1/3 anterior chamber may</td></tr><tr><td>require paracentesis</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"You are in charge of a busy evening shift when the buzzer goes off in one of the resus bays. Your registrar has just administered IV ketamine for procedural sedation to suture a forehead laceration of a 4-year-old girl. The child vomited and was then noted to become red in the face with stridor and reducing O2 sats. She is now apnoeic and becoming bradycardic. Central pulse is still palpable.","parts":[{"id":"a","label":"Part A","prompt":"List four (4) possible causes for this episode. (4 marks) 1. 2. 3. 4."},{"id":"b","label":"Part B","prompt":"State your immediate actions in a stepwise approach including drug doses where appropriate (8 marks) 1. 2. 3. 4. 5. 6. 7. 8.\nP a g e 4 | 39"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Laryngospasm</div><div class=\"answer-line\">Anaphylaxis</div><div class=\"answer-line\">Underlying comorbidity e.g. secondary to head injury/ seizure disorder etc</div><div class=\"answer-line\">Aspiration/FB</div><div class=\"answer-line\">Oversedation of respiratory drive from oversedation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>i.</td><td>Open airway : jawthrust, head in neutral position and midline</td></tr><tr><td>ii.</td><td>Suction gently under direct vision</td></tr><tr><td>iii.</td><td>Two-handed BVM with 100% FiO2, PEEP 10cmH2O + pressure in Larson’s notch</td></tr><tr><td colspan=\"2\">bilaterally</td></tr><tr><td>iv.</td><td>Give IMI adrenaline 10mcg/kg (= 0.01mL/kg 1:1000)</td></tr><tr><td>v.</td><td>Deepen sedation with a low dose Propofol (1 mg/kg) IV</td></tr><tr><td>vi.</td><td>Atropine 0.02mg/kg for bradycardia</td></tr><tr><td>vii.</td><td>If above fail, paralyse with sux 2mg/kg IV and proceed to intubate and ventilate</td></tr><tr><td colspan=\"2\">patient</td></tr><tr><td>viii.</td><td>Delegate a staff member to parents</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"You are the expedition doctor for a tour group of adults completing a 3-week trek in the Nepalese Himalayas. Highest planned altitude reached is 5,650m (18,500ft).","parts":[{"id":"a","label":"Part A","prompt":"Complete the table below listing two (2) climb and two (2) patient risk factors for development of altitude illness. (4 marks)"},{"id":"b","label":"Part B","prompt":"List two (2) key clinical features of the following conditions. (4 marks) Acute Mountain Sickness High Altitude Cerebral Oedema\nP a g e 5 | 39\nFive days into the trek at an altitude of 4200m, one of the climbers develops breathing difficulties. Portable oximeter shows a reading of 86%. You suspect high altitude pulmonary\n• edema."},{"id":"c","label":"Part C","prompt":"State the key steps in your management including any medications. (4 marks) Key Management Steps\nP a g e 6 | 39"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Rate of ascent</td><td>Prior history of altitude illness</td></tr><tr><td>Altitude attained</td><td>Obesity / OSA</td></tr><tr><td>Time at peak altitude</td><td>Underlying chronic respiratory disease</td></tr><tr><td>Degree of exertion at altitude</td><td>ETOH / benzo / sedative use at altitude</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Acute Mountain Sickness </strong> : headache, nausea / anorexia, weakness, lassitude</div><div class=\"answer-line\"><strong>High altitude cerebral oedema </strong>: ataxia, altered mental status, coma</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Arrange immediate descent where possible</div><div class=\"answer-line\">Supplemental oxygen, titrate to sats &gt; 90%</div><div class=\"answer-line\">Simulated descent if descent not possible (Gamow bag)</div><div class=\"answer-line\">Medication (any one of): Nifedipine SR 20mg TDS / Tadalafil 10mg BD / Salmeterol 125mcg BD</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 59-year-old man, well-known to your department with alcohol dependence and chronic\npancreatitis, presents with a 2-day history of epigastric pain. He has been given some analgesia and bloods are pending. While waiting to be seen, he is noted to become progressively dyspnoeic and you are asked to review him urgently. A CXR is performed and shown below :\nP a g e 7 | 39","parts":[{"id":"a","label":"Part A","prompt":"List one (1) relevant positive and one (1) relevant negative finding on this CXR. (2 marks) Positive Finding Negative Finding"},{"id":"b","label":"Part B","prompt":"What is the MOST LIKELY cause of these findings? (1 mark)"},{"id":"c","label":"Part C","prompt":"Complete the table below listing five (5) cardiogenic and five (5) noncardiogenic causes of pulmonary oedema (10 marks)"},{"id":"d","label":"Part D","prompt":"What ventilation strategy would you employ? Include relevant endpoints. (5 marks) Variable Setting Tidal volume PEEP\n\nRR\nOxygenation goal Position\nP a g e 9 | 39"}],"propPages":["asset:img16d7bc855898c6a6d3"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Positive: Diffuse/ bilateral interstitial infiltrates</div><div class=\"answer-line\">Negative: No pleural effusions, no Kerley B lines, no pneumoperitoneum</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Acute Respiratory Distress Syndrome (ARDS) secondary to pancreatitis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">Negative pressure pulmonary oedema (Re-</td></tr><tr><td>cardioversion, Takotsubo, Peripartum)</td><td>expansion, airway obstruction)</td><td></td></tr><tr><td><strong>2. </strong></td><td>Hypertension</td><td>Neurogenic pulmonary oedema</td></tr><tr><td><strong>3. </strong></td><td>ACS/ Myocardial ischaemia</td><td>High altitude pulmonary oedema</td></tr><tr><td><strong>4. </strong></td><td>Acute Valvular dysfunction (Severe AS, MR)</td><td>Post immersion pulmonary oedema</td></tr><tr><td><strong>5. </strong></td><td>Dysrhythmia</td><td>Hypertensive emergency (eg eclampsia, cocaine</td></tr><tr><td colspan=\"3\">induced)</td></tr><tr><td colspan=\"3\">High output cardiac failure (Hyperthyroidism, anaemia, AVM)</td></tr><tr><td colspan=\"3\"><strong>d)</strong><strong> </strong><strong> The patient is progressively dyspneic and is intubated.  What ventilation strategy would </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">4-6mL/kg IBW, titrate to PPlat &lt;30 (minimum 4mL/kg and pH &gt;7.15)</td></tr><tr><td><strong>PEEP </strong></td><td>Minimum 5cmH20 and up titrate to achieve oxygenation</td></tr><tr><td><strong>RR </strong></td><td>16-18, titrate to aim pH&gt; 7.2 (max RR 35)</td></tr><tr><td><strong>Oxygenation goal </strong></td><td>SpO2 &gt;90%, PaO2 60mmHg</td></tr><tr><td><strong>Position </strong></td><td>Consider prone positioning</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A man in his 30s is brought in by ambulance after collapsing at a party. He is now alert but deeply cyanotic despite receiving supplemental oxygen at 15L/min via NRBM. You immediately suspect methaemoglobinaemia.","parts":[{"id":"a","label":"Part A","prompt":"What drug is he MOST LIKELY to have ingested to cause this? (1 mark)"},{"id":"b","label":"Part B","prompt":"List three (3) other therapeutic drugs from different classes that can cause methaemoglobinaemia. (3 marks) Drug Class Drug You obtain an urgent ABG which shows a metHb level of 50%."},{"id":"c","label":"Part C","prompt":"List two (2) general indications for treatment with methylene blue. (2 marks) 1. 2.\nP a g e 10 | 39"},{"id":"d","label":"Part D","prompt":"List two (2) contraindications for methylene blue with their potential risks. (2 marks) Contraindications Risks 1. 2. The patient has neither of these contraindications."},{"id":"e","label":"Part E","prompt":"How would you administer methylene blue? Give dose and endpoints. (2 marks) Initial dose Repeat"},{"id":"f","label":"Part F","prompt":"List two (2) alternative treatment modalities if methylene blue is ineffective or contraindicated. (2 marks) 1. 2.\nP a g e 11 | 39"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Amyl nitrate</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Antibiotics</td><td>sulfonamides, dapsone</td></tr><tr><td>Antimalarial</td><td>chloroquine, hydroxychloroquine<strong> </strong></td></tr><tr><td>Local anaesthetics</td><td>benzocaine, prilocaine (rarely lignocaine)<strong> </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Asymptomatic + MetHb &gt; 25%</div><div class=\"answer-line\">Lower levels eg MetHb &gt; 10% in the presence of cardiorespiratory comorbidities</div><div class=\"answer-line\"><em>Answers above are in the context of this poisoning.  As wording asks for general indications would </em></div><div class=\"answer-line\"><em>accept : vasoplegic shock post cardiopulmonary bypass, hepatorenal syndrome, sepsis  </em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Acute haemolysis</div><div class=\"answer-line\"><strong>2. </strong></div><div class=\"answer-line\">SSRIs</div><div class=\"answer-line\">Serotonin Syndrome</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">1-2mg/kg (0.1-0.2mL/kg of 1% solution) IV over 5 minutes</div><div class=\"answer-line\"><strong>Repeat </strong></div><div class=\"answer-line\">Repeat in 30-60 minutes if MetHb level &gt; 20%</div><div class=\"answer-line\">Do not exceed 7mg/kg -&gt; haemolysis</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">Ascorbic acid up to 10g IV</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"You are asked to urgently assess a 14-year-old boy with severe autism who has been brought into ED by his distressed parents. He has been physically aggressive towards his family and engaged in head-banging behaviour today resulting in a large oozing haematoma on his forehead. This behaviour has occurred episodically in the past. He has been placed in a resus bay where you find him screaming and flailing with 2 security\n• fficers trying to stop him from running away. He weighs approximately 50kg and is 160cm\ntall.","parts":[{"id":"a","label":"Part A","prompt":"List four (4) common medical causes of acute aggression in children with autism spectrum disorder. (4 marks) 1. 2. 3. 4."},{"id":"b","label":"Part B","prompt":"List four (4) general principles which can facilitate assessment and management of children with severe autism. (4 marks) 1. 2. 3. 4.\nP a g e 12 | 39\nYour attempts to de-escalate the situation are unsuccessful and sedation is now required."},{"id":"c","label":"Part C","prompt":"List two (2) sedation options for this patient giving dose/route and one (1) potential risk. (4 marks) Drug including dose and route Risk\nP a g e 13 | 39"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Infection</strong> : chest, UTI, OM and/or OE</div><div class=\"answer-line\"><strong>Abdominal pathology</strong> eg constipation, appendicitis, inflammatory bowel disease</div><div class=\"answer-line\">Any other occult causes of pain (dental pathology, fractures, inguino-scrotal conditions)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Engage and effectively utilise parents/carers</div><div class=\"answer-line\">Use communication / visual aids as appropriate</div><div class=\"answer-line\">Reduce environmental stimulation</div><div class=\"answer-line\">If possible, reduce number of people dealing with child</div><div class=\"answer-line\">Nontactile physical examination</div><div class=\"answer-line\">Stepwise de-escalation</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Olanzapine (1 dose only)</td><td>Dystonia</td></tr><tr><td>PO wafer &gt;40kg 5-10mg</td><td>(serotonin syndrome/NMS)</td></tr><tr><td colspan=\"2\">IM/IV 2.5-10mg</td></tr><tr><td>Droperidol</td><td>QT prolongation</td></tr><tr><td>IM 0.1-0.2mg/kg (max 10mg)</td><td>Dystonia</td></tr><tr><td>Repeat in 15min</td><td>Respiratory depression</td></tr><tr><td>Midazolam</td><td><strong>Disinhibition </strong></td></tr><tr><td>IM / IV 0.1-0.2mg/kg</td><td>Under/oversedation</td></tr><tr><td colspan=\"2\">Respiratory depression</td></tr><tr><td colspan=\"2\">Large doses usually required</td></tr><tr><td>Ketamine</td><td>Emergence phenomena / subdissociative</td></tr><tr><td>IM 4mg/kg, IV 1mg/kg</td><td>agitation</td></tr><tr><td colspan=\"2\">(Laryngospasm)</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"The bedside nurse has asked you to check position of this NGT on CXR, inserted by one of your medical students.","parts":[{"id":"a","label":"Part A","prompt":"List three (3) relevant findings on this image. (3 marks) 1. 2. 3.\nP a g e 14 | 39"},{"id":"b","label":"Part B","prompt":"List three (3) immediate clinical actions you would take. (3 marks) 1. 2. 3."},{"id":"c","label":"Part C","prompt":"List six (6) steps you would take in managing this incident. (6 marks) 1. 2. 3. 4. 5. 6.\nP a g e 15 | 39"}],"propPages":["asset:imgd6cd074a13b9fbbcbd"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">NGT has gone down R main bronchus</div><div class=\"answer-line\"><strong>2. </strong></div><div class=\"answer-line\">Iatrogenic R-sided pneumothorax</div><div class=\"answer-line\"><strong>3. </strong></div><div class=\"answer-line\">R basal opacification – unlikely to be fluid as would expect horizontal air-fluid interface</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Immediate removal of misplaced NGT</div><div class=\"answer-line\"><strong>2. </strong></div><div class=\"answer-line\">Supportive : ensure patient clinically stable, provide oxygen and analgesia</div><div class=\"answer-line\"><strong>3. </strong></div><div class=\"answer-line\">Insert R small-bore ICC to treat iatrogenic injury<strong> </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Open disclosure</strong> of event to patient / relatives</td></tr><tr><td><strong>2. </strong></td><td><strong>Document</strong> the incident and discussion with patient</td></tr><tr><td><strong>3. </strong></td><td><strong>Notify incident</strong> via hospital’s Incident Management Database</td></tr><tr><td><strong>4. </strong></td><td><strong>Counsel / debrief</strong> the student and the supervising RN / MO</td></tr><tr><td colspan=\"2\">Notify student’s clinical supervisor and review policy/procedure for clinical supervision of</td></tr><tr><td colspan=\"2\"><strong>5. </strong></td></tr><tr><td colspan=\"2\">medical students</td></tr><tr><td><strong>6. </strong></td><td>Refer for review and education via M+M</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 68-year-old man is brought in by ambulance having been found collapsed in a shopping\ncentre. On arrival he is mottled and agitated with the following obs :\n\nTemp 34.5°C\n\nHR\n130 regular\n\nBP\n78/54\n\nRR\n\nSats\nunrecordable\n\nGCS\nE3V4M6 = 13 Focussed exam reveals clear chest, soft non-tender abdomen, unilateral leg swelling. You have no PMHx available at this time, other than a history of prostate cancer.","parts":[{"id":"a","label":"Part A","prompt":"Define massive PE. (1 mark)"},{"id":"b","label":"Part B","prompt":"List four (4) differentials for tachypnoea and shock with clear chest on examination. (4 marks) 1. 2. 3. 4.\nP a g e 16 | 39"},{"id":"c","label":"Part C","prompt":"List three (3) findings you might find on bedside cardiac ultrasound in the setting of massive PE. (3 marks) 1. 2. 3."},{"id":"d","label":"Part D","prompt":"State four (4) immediate management priorities, including doses and endpoints. (8 marks) Priority Treatment/dose/endpoint 10 minutes after initial resuscitation, the patient deteriorates into cardiac arrest and CPR is commenced.\nP a g e 17 | 39"},{"id":"e","label":"Part E","prompt":"In addition to the standard ALS algorithm, list two (2) measures which are indicated in managing this cardiac arrest. (2 marks) 1. 2.\nP a g e 18 | 39"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">PE with haemodynamic compromise with a SBP &lt; 90mmHg for &gt; 15 minutes</div><div class=\"answer-line\">(or profound bradycardia &lt; 40 with signs of shock, sustained SBP drop &gt; 40mmHg below</div><div class=\"answer-line\">baseline if known)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Pericardial tamponade</td></tr><tr><td><strong>2. </strong></td><td>Sepsis</td></tr><tr><td><strong>3. </strong></td><td>AMI</td></tr><tr><td><strong>4. </strong></td><td>Myocarditis</td></tr><tr><td>•</td><td>DKA<strong> </strong></td></tr><tr><td>•</td><td>Severe acute blood loss<strong> </strong></td></tr><tr><td>•</td><td>Salicylate poisoning<strong> </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>RV dilatation</strong> : diameter &gt; 2.5cm on PLAX view with normal wall thickness</td></tr><tr><td>•</td><td>Dilated IVC with lack of respiratory collapse</td></tr><tr><td>•</td><td>Flat intraventricular septum</td></tr><tr><td>•</td><td>McConnel’s sign – right free ventricle wall is hypokinetic / a kinetic but there is hyperkinesis or</td></tr><tr><td colspan=\"2\">normal movement at the apical segment (<em>can be seen in RV MI as well)</em></td></tr><tr><td>•</td><td>Clot in transit</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Optimise oxygenation</strong> : supplemental O2 titrated to sats &gt;94%<strong> </strong></td></tr><tr><td>•</td><td>Haemodynamic resuscitation :  <strong>fluid conservative approach</strong> as IVF may worsen RV dilatation –</td></tr><tr><td colspan=\"2\">judicious bolus followed by <strong>early vasopressors </strong>titrate to MAP &gt;65mmHg<strong> </strong></td></tr><tr><td>•</td><td><strong>Administration of thrombolysis </strong>(if no contraindications) : for patient &gt;65kg alteplease 10mg</td></tr><tr><td colspan=\"2\">IV bolus over 1-2 minutes followed by 90mg infusion over 2 hours</td></tr><tr><td>•</td><td>Consider cold sepsis : empiric antibiotics of 2g IV flucloxacillin and 5-7mg/kg gent stat dose</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">i.</div><div class=\"answer-line\">Alteplase 50mg IV push over 60 seconds</div><div class=\"answer-line\">ii.</div><div class=\"answer-line\">Prolonged CPR – ideally with LUCAS device – up to 1 hour or until ROSC</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 32-year-old lady presents with bloating, low abdominal pain and shortness of breath on\nminimal exertion. She is on the IVF program, had egg retrieval 13 days ago and transfer of\nan embryo 7 days ago.\nShe has been advised to present to emergency due to possible ovarian hyperstimulation syndrome (OHSS). You decide to investigate with bedside ultrasound and images are shown below : RUQ LUQ","parts":[{"id":"a","label":"Part A","prompt":"List two (2) features of ovarian hyperstimulation syndrome demonstrated in the ultrasound images. (2 marks) 1. 2.\nP a g e 19 | 39"},{"id":"b","label":"Part B","prompt":"If she develops severe lower abdominal pain, what is the most important complication of OHSS that must considered and why? (1 mark) Complication Reason"},{"id":"c","label":"Part C","prompt":"List three (3) additional complications of OHSS and state how they may be managed or prevented. (6 marks) Complication Prevention or Management Strategy 1. 2. 3.\nP a g e 20 | 39"}],"propPages":["asset:imgb0ffde1168d000c59a","asset:img8808870f72861261eb"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">i.</div><div class=\"answer-line\">Bilateral pleural effusions (spine sign bilaterally)</div><div class=\"answer-line\">ii.</div><div class=\"answer-line\">Ascites  (mild on these images)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Ovarian torsion - ovaries enlarged with multiple follicles, at risk of torsion</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Oliguric renal failure</td><td>Strict fluid balance, IDC, may require 4% albumin, avoid</td><td></td></tr><tr><td colspan=\"3\">diuretics</td></tr><tr><td><strong>2. </strong></td><td>Tense ascites</td><td>Paracentesis under ultrasound guidance</td></tr><tr><td colspan=\"3\">(Pleural/pericardial effusion)</td></tr><tr><td><strong>3. </strong></td><td>Thromboembolism (arterial and</td><td>TEDS/clexane</td></tr><tr><td>venous)</td><td>Therapeutic anticoagulation if confirmed</td><td></td></tr><tr><td>Electrolyte disturbance</td><td>Monitor and correct hypoNa and hyperK</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 40-year-old man presents to your ED at 11.30pm in severe pain and distress with an\nerection which has been present for the past 3 hours. He denies any significant PMHx.","parts":[{"id":"a","label":"Part A","prompt":"List four (4) points of differentiation between low-flow and high-flow priapism. (4 marks) Low Flow High Flow"},{"id":"b","label":"Part B","prompt":"List four (4) medications from different drug classes which can cause priapism. (4 marks) 1. 2. 3. 4.\nP a g e 21 | 39"},{"id":"c","label":"Part C","prompt":"Give one (1) option in the management of priapism as per the headings in the table below, including drug doses where relevant. (4 marks) Analgesia Non-invasive Invasive Specialised\nP a g e 22 | 39"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Ischaemic</td><td>Non-ischaemic</td></tr><tr><td>Venous obstruction</td><td>Increased arterial flow</td></tr><tr><td>Severe pain</td><td>Less symptomatic</td></tr><tr><td>Often medication induced or related to sickle</td><td>Caused by trauma – saddle injury, arterial</td></tr><tr><td>cell disease (atraumatic)</td><td>laceration, spinal trauma</td></tr><tr><td>Acidotic penile blood gas</td><td>Normal penile blood gas</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Intracavernosal injections :“triple mix” = papaverine + PGE1 + phentolamine</div><div class=\"answer-line\">PDE5 inhibitors : sildelfanil  (rare)</div><div class=\"answer-line\">AntiHT : hydralazine, prazosin, CCB</div><div class=\"answer-line\">Neuroleptics : trazodone, chlorpromazine, SSRI</div><div class=\"answer-line\">Drugs of abuse : cocaine, amphetamines, THC</div><div class=\"answer-line\">Lithium</div><div class=\"answer-line\">Anticoagulants</div><div class=\"answer-line\"><strong>c)</strong><strong> </strong><strong>Give one (1) management option as prescribed in the table below including drug doses where </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">PO/ IV analgesia</td></tr><tr><td colspan=\"2\">Dorsal penile block with plain lignocaine<strong> </strong></td></tr><tr><td><strong>Non-invasive </strong></td><td>Warm compresses</td></tr><tr><td colspan=\"2\">Exercise</td></tr><tr><td colspan=\"2\">Terbutaline 5-10mg PO (or 0.25-0.5mg SC)</td></tr><tr><td colspan=\"2\">Phenylephrine 60mg PO</td></tr><tr><td><strong>Invasive </strong></td><td>Lateral corporal aspiration bilaterally, 10-20mL avoiding neurovascular</td></tr><tr><td colspan=\"2\">bundle and urethra <em>(35% resolve with aspiration alone)</em></td></tr><tr><td colspan=\"2\">Corporal irrigation with 25mL cold sterile saline if detumescence does not</td></tr><tr><td colspan=\"2\">occur after 2 aspiration attempts</td></tr><tr><td colspan=\"2\">Intracorporeal vasoconstrictor : phenylephrine injection <em>(dilute 100mcg/mL </em></td></tr><tr><td colspan=\"2\"><em>and inject 1-2mL q5 min to max 1mg over 1 hr) </em>OR adrenaline 1:100000</td></tr><tr><td colspan=\"2\">injection 1-2mL to max 10mL<em> </em></td></tr><tr><td><strong>Specialised </strong></td><td>Exchange transfusion in sickle cell disease</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 32-year-old female is brought into the ED by ambulance. She had been found in an alley\nintoxicated and agitated, informing staff that she needs to find her husband who had left her in the street because they had had a fight. You note multiple bruises on her upper arm in keeping with finger marks.","parts":[{"id":"a","label":"Part A","prompt":"List the four (4) components of the HITS tool for intimate partner violence screening. (2 marks) How often does your partner...? 2. 3. 4."},{"id":"b","label":"Part B","prompt":"Aside from women, list (six) 6 cohorts of people who are most at risk of domestic violence. (6 marks) 1. 2. 3. 4. 5. 6.\nP a g e 23 | 39"},{"id":"c","label":"Part C","prompt":"List four (4) circumstances / behaviours that constitute a high risk (increased likelihood of death) to the victim. (4 marks) 1. 2. 3. 4.\nP a g e 24 | 39"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Physically HURT you</td></tr><tr><td><strong>2. </strong></td><td>INSULT or talk down to you</td></tr><tr><td><strong>3. </strong></td><td>THREATEN you with harm</td></tr><tr><td><strong>4. </strong></td><td>SCREAM or curse at you</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">People identifying as LGBTI</td></tr><tr><td><strong>2. </strong></td><td>People living with a disability</td></tr><tr><td><strong>3. </strong></td><td>Children</td></tr><tr><td><strong>4. </strong></td><td>Older persons</td></tr><tr><td><strong>5. </strong></td><td>Aboriginal and Torres Strait Islander peoples</td></tr><tr><td><strong>6. </strong></td><td>Culturally and linguistically diverse communities (CALD)</td></tr><tr><td colspan=\"2\">People in rural and remote Australia</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">New pregnancy</td></tr><tr><td><strong>2. </strong></td><td>Recent or planned separation</td></tr><tr><td><strong>3. </strong></td><td>Non-fatal strangulation</td></tr><tr><td><strong>4. </strong></td><td>Harm to pets</td></tr><tr><td colspan=\"2\">Threats to kill</td></tr><tr><td colspan=\"2\">Access to weapons</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"You are the consultant in a rural Emergency Dept when the triage nurse alerts you to the\narrival of a 15-month-old boy with lethargy & vomiting.\nThe child was found in the back seat of a car at the local RSL club car park. Outside temperature is 38°C. The child is moved straight into the resuscitation area and monitoring is placed. Vital signs are recorded as follows :\n\nTemp (tympanic)\n39.6°C\n\nHR\n160 bpm\n\nRR\n28/min\n\nSaO2\n90% on RA P on AVPU scale","parts":[{"id":"a","label":"Part A","prompt":"List two (2) physiological characteristics of children which make them more susceptible to heat-related illness compared to adults (2 marks) 1. 2. Initial resuscitative measures have been commenced on your patient. Core rectal\ntemperature is measured at 40.2°C.\nP a g e 25 | 39"},{"id":"b","label":"Part B","prompt":"Prioritise a list of four (4) methods you would use to rapidly cool this child. (4 marks) 1. 2. 3. 4."},{"id":"c","label":"Part C","prompt":"Complete the table below listing one (1) serious organ system effect of heat stroke and the result of one (1) relevant investigation (12 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Higher basal metabolic rate than adults -&gt; produce more heat</td></tr><tr><td>•</td><td>Higher surface area : mass ratio resulting in greater heat absorption in hot environments</td></tr><tr><td>•</td><td>Smaller absolute blood volume resulting in lower blood-borne heat dissipation from core</td></tr><tr><td colspan=\"2\">to surface</td></tr><tr><td>•</td><td>Lower rate of sweating than adults -&gt; begin sweating at higher temperatures</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Remove clothes </strong></td></tr><tr><td>•</td><td><strong>Evaporative cooling : tepid water spray and fan </strong></td></tr><tr><td>•</td><td>Cool IVF (some sources recommend room temp)<strong> </strong></td></tr><tr><td>•</td><td>Ice packs to neck, groin and axillae<strong> </strong></td></tr><tr><td colspan=\"2\"><strong>NOT antipyretics </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td><strong>Neurologic </strong></td><td>Cerebral oedema</td><td>HypoNa</td></tr><tr><td>Seizures</td><td>Hypoglycaemia</td><td></td></tr><tr><td colspan=\"3\">CT brain : features of cerebral oedema</td></tr><tr><td><strong>Cardiovascular </strong></td><td>Tachyarrhythmia</td><td>ECG :  tachyarrhythmias</td></tr><tr><td colspan=\"3\">Hypotension / shock</td></tr><tr><td><strong>Renal/Metabolic </strong></td><td>Acute kidney Injury</td><td>Elevated U + Cr</td></tr><tr><td>Rhabdomyolysis</td><td>Elevated CK, hypoCa</td><td></td></tr><tr><td><strong>Haematologic </strong></td><td>DIC</td><td>Raised INR &amp; D-Dimer</td></tr><tr><td colspan=\"3\">Low fibrinogen</td></tr><tr><td><strong>Gastrointestinal </strong></td><td>Hepatic Injury</td><td>Elevated / deranged LFT</td></tr><tr><td><strong>Respiratory </strong></td><td>Cardiogenic/noncardiogenic</td><td>CXR : bilateral patchy opacification</td></tr><tr><td colspan=\"3\">pulmonary oedema</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 72-year-old man from home with his wife, is brought in by ambulance after a fall. He reports losing balance and falling forward, hitting his head on a window-sill then landing prone on the ground. He has full recall of events and complains of neck pain. Only past medical history is early Parkinsons Disease. On brief initial examination his obs are unremarkable and there does not appear to be any significant neuro deficit. He is immobilised in a hard C-spine collar. You arrange urgent CT brain and C-spine, a section of which shown below :","parts":[{"id":"a","label":"Part A","prompt":"List two (2) concerning features on the CT image. (2 marks) 1. 2.\nP a g e 27 | 39\nThis appears to be the only sequelae of trauma on examination and relevant imaging."},{"id":"b","label":"Part B","prompt":"List five (5) specific complications you might anticipate from this injury and state how you would mitigate / manage each if required. Give drug doses and endpoints where relevant. (10 marks) Complication Management\nP a g e 28 | 39"}],"propPages":["asset:imgfca15831425ef89ff2"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Type II dens fracture</div><div class=\"answer-line\"><strong>2. </strong></div><div class=\"answer-line\">Posterior displacement of approximately 3mm</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td><strong>Worsening prevertebral </strong></td><td>Careful emergent intubation, ideally fibreoptic,</td></tr><tr><td><strong>oedema/hematoma occluding airway </strong></td><td>but shown to be safe with VL RSI with</td></tr><tr><td colspan=\"2\">MILS/bougie/most experienced operator</td></tr><tr><td><strong>Respiratory failure</strong> – C2 high risk<strong> </strong></td><td>Intubation (as above) if VC &lt; 30% predicted, poor</td></tr><tr><td colspan=\"2\">cough – oxygenation and ventilation to</td></tr><tr><td colspan=\"2\">normoxia/normocapnia</td></tr><tr><td><strong>Neurogenic shock</strong> – injury above T6</td><td>Art line, judicious fluid resus, early vasopressor</td></tr><tr><td colspan=\"2\">infusion (noradrenaline) titrated to MAP &gt;85-</td></tr><tr><td colspan=\"2\">90mmHg, (atropine for bradycardia to HR &gt;</td></tr><tr><td colspan=\"2\">60bpm if BP inadequate)</td></tr><tr><td><strong>Cervical myelopathy / cord injury</strong> from</td><td>Appropriate C-spine immobilisation (Phile, Miami</td></tr><tr><td>vertebral compression</td><td>J, Aspen) with strict spinal precautions (entire</td></tr><tr><td colspan=\"2\">spine), careful logroll</td></tr><tr><td>Pressure areas</td><td>Q2H repositioning (air mattress)</td></tr><tr><td>Urinary retention</td><td>IDC insertion</td></tr><tr><td>Aspiration due to gastroparesis, reduced</td><td>Early NGT insertion, NBM</td></tr><tr><td colspan=\"2\">GOS tone</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 50-year-old man presents with fever, throat pain and increasing shortness of breath . On examination he has tenderness in the anterior neck and fullness under the chin. His vitals are as follows :\n\nTemp 38.5°C\n\nHR\n110/min\n\nBP\n90/60\n\nRR\n\nSaO2 95% on RA\nContrast CT of his neck is obtained and is shown below :\nP a g e 29 | 39","parts":[{"id":"a","label":"Part A","prompt":"List three (3) pertinent findings on the CT. (3 marks) 1. 2. 3."},{"id":"b","label":"Part B","prompt":"List three (3) approaches to securing this patient’s airway along with with one (1) benefit and one (1) risk of each. (9 marks) Approach Benefit Risk\nP a g e 30 | 39"}],"propPages":["asset:imgd2979270e448661ff3"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>i.</td><td>Extensive anterior/soft tissue swelling and stranding in keeping with infective process</td></tr><tr><td>ii.</td><td>Free gas anterior neck</td></tr><tr><td>iii.</td><td>Trachea patent and midline</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Standard RSI with</td><td>Familiar to ED staff</td><td>High failure in Ludwig’s Angina</td></tr><tr><td>VL/DL</td><td>(50%)</td><td></td></tr><tr><td>Fibreoptic awake</td><td>Lower risk than RSI, clear</td><td>Lack of equipment, unfamiliar skill</td></tr><tr><td>assessment of airway anatomy</td><td>in ED</td><td></td></tr><tr><td>Surgical airway</td><td>Definitive airway</td><td>Distorted anatomy (soft tissue</td></tr><tr><td colspan=\"3\">swelling and gas) will make it very</td></tr><tr><td colspan=\"3\">difficult</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 22-year-old man presents to ED after being involved in a street fight. No weapons were\nused. He has pain in his mouth and complains of blurred vision. On examination of his mouth you see this :","parts":[{"id":"a","label":"Part A","prompt":"List three (3) positive findings seen in the image. (3 marks) 1. 2. 3.\nP a g e 31 | 39"},{"id":"b","label":"Part B","prompt":"What other injuries would you assess for in this patient? (6 marks) 1. 2. 3. 4. 5. 6."},{"id":"c","label":"Part C","prompt":"What approaches to analgesia are available to this patient? Include appropriate doses. (3 marks) 1. 2. 3.\nP a g e 32 | 39"}],"propPages":["asset:img66586baefb2a81b7dd"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Complete avulsion of 1.1 and laceration to gum with disruption of alveolar ligament</div><div class=\"answer-line\">Complete avulsion of 2.1</div><div class=\"answer-line\">Extrusive subluxation of 2.2</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Facial/maxilla/mandibular fracture</div><div class=\"answer-line\">Orbital fracture (with EOM entrapment)</div><div class=\"answer-line\">Traumatic eye injury</div><div class=\"answer-line\">Nasal fracture +/- septal hematoma</div><div class=\"answer-line\">Evidence of BOS fracture</div><div class=\"answer-line\">Cervical spine injury (ie hyperextension force)</div><div class=\"answer-line\">Soft tissue injuries in mouth (tongue/buccal mucosa)</div><div class=\"answer-line\">Hand injuries (fight bites, hand fractures)<em>  </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>i.</td><td>PO analgesia with doses</td></tr><tr><td>ii.</td><td>IV analgesia with doses</td></tr><tr><td>iii.</td><td>Regional nerve block : maxillary / infraorbital</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"You are looking after a 10-week-old male infant who presented febrile and listless. Urgent bloods results have been called through from the lab and are shown below : Reference Range Sodium 133 135-145 mmol/L Potassium 8.2 3.5-5.2 mmol/L Chloride 104 95-110 mmol/L Calcium Ionised 0.84 0.95-1.50 mmol/L Blood Glucose 7.2 3.9-6.1 mmol/L Blood Lactate 3.8 0.2-2.0 mmol/L\n\nWCC\n344.13 6.5-17.5 x10^9/L\n\nHb\n95-135 g/L PLT 150-450 x10^9/L HCT 0.178 0.29-0.41 L/L MCV 104.7 72-82 fL RCC 1.70 4.5-6.5 x10^12/L","parts":[{"id":"a","label":"Part A","prompt":"Provide an explanation for five (5) abnormalities (other than K+) in these results. (5 marks)"},{"id":"b","label":"Part B","prompt":"List a possible complication related to four (4) of the abnormal blood results (4) Abnormal value Complication"},{"id":"c","label":"Part C","prompt":"What is the most likely diagnosis? (1 mark) An ECG is performed and shown below :\nP a g e 34 | 39"},{"id":"d","label":"Part D","prompt":"List four (4) normal ECG parameter differences between an infant and adult ECG (4 marks)"},{"id":"e","label":"Part E","prompt":"Outline your approach to his K+ result. (4 marks) 1. 2. 3. 4.\nP a g e 35 | 39"}],"propPages":["asset:img62fe3857a9f8c37e94"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">You are looking after a 10-week-old male infant who presented febrile and listless.  Urgent bloods</div><div class=\"answer-line\">results have been called through from the lab and are shown below :</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Sodium</td><td>133</td><td>135-145 mmol/L</td></tr><tr><td>Potassium</td><td>8.2</td><td>3.5-5.2 mmol/L</td></tr><tr><td>Chloride</td><td>104</td><td>95-110 mmol/L</td></tr><tr><td>Calcium Ionised</td><td>0.84</td><td>0.95-1.50 mmol/L</td></tr><tr><td>Blood Glucose</td><td>7.2</td><td>3.9-6.1 mmol/L</td></tr><tr><td>Blood Lactate</td><td>3.8</td><td>0.2-2.0 mmol/L</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>WCC</td><td>344.13</td><td>6.5-17.5 x10^9/L</td></tr><tr><td>Hb</td><td>64</td><td>95-135 g/L</td></tr><tr><td>PLT</td><td>33</td><td>150-450 x10^9/L</td></tr><tr><td>HCT</td><td>0.178</td><td>0.29-0.41 L/L</td></tr><tr><td>MCV</td><td>104.7</td><td>72-82 fL</td></tr><tr><td>RCC</td><td>1.70</td><td>4.5-6.5 x10^12/L</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><strong>Abnormality </strong></div><div class=\"answer-line\"><strong>Explanation/Cause </strong></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">________________________________________________________________________</div><div class=\"answer-line\"><strong>An ECG is performed and shown below :  </strong></div><div class=\"answer-line\"><strong>Infant Parameter </strong></div><div class=\"answer-line\"><strong>Adult Parameter </strong></div><div class=\"answer-line\"><strong>2. </strong></div><div class=\"answer-line\"><strong>3. </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false,"investigationTables":[{"id":"investigation-1","title":"Blood results","headers":["Test","Result","Reference Range"],"rows":[["Sodium","133","135-145 mmol/L"],["Potassium","8.2","3.5-5.2 mmol/L"],["Chloride","104","95-110 mmol/L"],["Calcium Ionised","0.84","0.95-1.50 mmol/L"],["Blood Glucose","7.2","3.9-6.1 mmol/L"],["Blood Lactate","3.8","0.2-2.0 mmol/L"],["WCC","344.13","6.5-17.5 x10^9/L"],["Hb","64","95-135 g/L"],["PLT","33","150-450 x10^9/L"],["HCT","0.178","0.29-0.41 L/L"],["MCV","104.7","72-82 fL"],["RCC","1.70","4.5-6.5 x10^12/L"]]}]},{"number":17,"title":"","stemText":"A 22-year old male presents with an episode of syncope during a game of tennis. He reports no prodromal symptoms prior to the collapse. He has had one similar episode in the past, also while playing tennis. On examination, he appears well. Vital signs are: HR 60 bpm; BP 115/70; RR 12; SaO2 98% RA; Temp 36.5C His ECG is shown below :","parts":[{"id":"a","label":"Part A","prompt":"List two (2) salient positive findings on the ECG. (2 marks) 1. 2."},{"id":"b","label":"Part B","prompt":"Most likely diagnosis? (1 mark)\nP a g e 36 | 39"},{"id":"c","label":"Part C","prompt":"List two (2) specific signs would you assess for on physical examination. (2 marks) 1. 2."},{"id":"d","label":"Part D","prompt":"List three (3) potential causes of presyncope / syncope related to this condition. (3 marks) 1. 2. 3."},{"id":"e","label":"Part E","prompt":"List and justify two (2) specific investigations for this condition. (2 marks) Test Rationale"},{"id":"f","label":"Part F","prompt":"The patient requests to go home. What advice would you provide? (2 marks) 1. 2.\nP a g e 37 | 39"}],"propPages":["asset:imgd8d1fb55e240d46268"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Meets LVH criteria (R in V2 + S in V5 &gt; 35mm)</div><div class=\"answer-line\"><strong>2. </strong></div><div class=\"answer-line\">Dagger Q waves in I, V5, V6 (&lt; 40ms)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Hypertrophic cardiomyopathy</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Crescendo systolic murmur increased with Valsalva / squat to stand : LVOT obstruction </strong></div><div class=\"answer-line\"><strong>2.</strong><strong> </strong></div><div class=\"answer-line\">Mid-late systolic murmur apex -&gt; axilla : mitral regurgitation</div><div class=\"answer-line\"><strong>  </strong>Other<strong> : </strong>S3/S4, Prominent “a” wave JVP, ventricular heave / prominent apical impulse</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Dysrhythmias eg AF, SVT, ventricular</div><div class=\"answer-line\"><strong>3. </strong></div><div class=\"answer-line\">Conduction abnormalities</div><div class=\"answer-line\">Myocardial ischaemia</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Assess for LVOT obstruction /ASH / SAM / apical thickening / LA</div><div class=\"answer-line\">dilatation / MR</div><div class=\"answer-line\">Holter monitor</div><div class=\"answer-line\">Assess for supraventricular and ventricular dysrhythmias</div><div class=\"answer-line\">Cardiac MRI – to confirm diagnosis of HOCM</div><div class=\"answer-line\">Exercise testing – risk stratification prior to commencement of treatment</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">Discharge is ok if feels well, but needs close outpatient follow up with cardiologist, echo,</div><div class=\"answer-line\">holter etc</div><div class=\"answer-line\"><strong>2. </strong></div><div class=\"answer-line\"><strong>NOT to participate in active sports until cleared by cardiologist </strong><strong> </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 32-year-old male presents with fever and atraumatic unilateral knee pain and swelling.","parts":[{"id":"a","label":"Part A","prompt":"What organisms would be likely to cause septic arthritis in this patient? (3 marks) 1. 2. 3."},{"id":"b","label":"Part B","prompt":"List three (3) contraindications for joint aspiration in the ED. (3 marks) 1. 2. 3. Unfortunately, your registrar sustains a needle stick injury after aspirating the joint.\nP a g e 38 | 39"},{"id":"c","label":"Part C","prompt":"Briefly outline your six (6) management priorities. (6 marks) 1. 2. 3. 4. 5. 6.\nP a g e 39 | 39"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">S. aureus</div><div class=\"answer-line\"><strong>3. </strong></div><div class=\"answer-line\">Group A strep (S pyogenes)<em><strong> </strong></em></div><div class=\"answer-line\">Pseudomonas / E coli (GN in IVDU)</div><div class=\"answer-line\"><em>(should mention N gonorrhoea for pass) </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Coagulopathy INR &gt; 3</div><div class=\"answer-line\"><strong>2. </strong></div><div class=\"answer-line\">Overlying cellulitis</div><div class=\"answer-line\"><strong>3. </strong></div><div class=\"answer-line\">Prosthetic joint</div><div class=\"answer-line\">Adjacent fracture / osteomyelitis</div><div class=\"answer-line\"><em>(Patient refusal/uncooperative weak answer) </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>First aid</strong> of exposed person : wash with soap and water</td></tr><tr><td><strong>2. </strong></td><td><strong>Undertake a risk assessment for the exposure</strong></td></tr><tr><td colspan=\"2\">- Exposure date/time/type</td></tr><tr><td colspan=\"2\">- Source person BBV status/demographic factors</td></tr><tr><td colspan=\"2\">- Exposed person BBV status/immunisation/medical history</td></tr><tr><td><strong>3. </strong></td><td><strong>Obtain bloods from source and exposed</strong> including HepB/HepC/HIV serology</td></tr><tr><td><strong>4. </strong></td><td>Based on risk assessment, <strong>provide counselling and treatment as indicated</strong> :</td></tr><tr><td colspan=\"2\">- HIV testing and post exposure prophylaxis, start within 1hr of injury if high risk</td></tr><tr><td colspan=\"2\">exposure</td></tr><tr><td colspan=\"2\">- Hep B status - if not immune needs Hep B Ig and immunisation</td></tr><tr><td><strong>5. </strong></td><td><strong>Arrange follow-up and counsel re : not donating blood, falling pregnant, reporting febrile </strong></td></tr><tr><td colspan=\"2\"><strong>illness for next 3 months </strong></td></tr><tr><td colspan=\"2\">- Arrange staff health / GP for repeat tests in 6 weeks and 3 months</td></tr><tr><td><strong>6. </strong></td><td>Detailed <strong>documentation</strong> of events and <strong>incident notification </strong></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
